import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Remove near-duplicates based on correlation
    correlated_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:, i], feats.x[:, j])[0,1]) >= 0.6:
                correlated_pairs.add((min(fid1, fid2), max(fid1, fid2)))

    # Build set of unique features (remove duplicates)
    unique_features = set(feats.ids)
    for p1, p2 in correlated_pairs:
        if p1 != p2:
            unique_features.discard(p2)  # Keep only first of pair

    # Filter features to unique ones
    filtered_ids = tuple(f for f in feats.ids if f in unique_features)
    filtered_x = feats.x[:, [feats.column(fid) for fid in filtered_ids]]

    # Select top features by t-statistic (absolute value)
    t_stats = []
    for i, fid in enumerate(filtered_ids):
        y0 = feats.y[feats.x[:, feats.column(fid)] < np.mean(feats.x[:, feats.column(fid)])]
        y1 = feats.y[feats.x[:, feats.column(fid)] > np.mean(feats.x[:, feats.column(fid)])]
        if len(y0) > 0 and len(y1) > 0:
            t_stat, _ = stats.ttest_ind(y1, y0)
        else:
            t_stat = 0
        t_stats.append(abs(t_stat))

    # Sort by t-statistic descending
    sorted_indices = np.argsort(t_stats)[::-1][:MAX_DRIVERS]
    drivers = tuple(filtered_ids[i] for i in sorted_indices if t_stats[i] > 2.0)

    # If no strong drivers found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build columns and products from top features
    columns = drivers
    products = []

    # Add pairwise interactions between top drivers
    for i in range(len(drivers)):
        for j in range(i+1, len(drivers)):
            if abs(np.corrcoef(
                feats.x[:, feats.column(drivers[i])],
                feats.x[:, feats.column(drivers[j])]
            )[0,1]) < 0.7:  # Avoid highly correlated pairs
                products.append((drivers[i], drivers[j]))

    # Create weighted loading score using top features
    loadings = {}
    for i, fid in enumerate(columns):
        # Use standardized coefficients from a simple linear regression
        coef = np.corrcoef(feats.x[:, feats.column(fid)], feats.y)[0,1]
        loadings[fid] = coef

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

